'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64Array = require( '@stdlib/array/complex64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var cindexOfColumn = require( './../lib' );


// FUNCTIONS //

/**
* Returns a two-dimensional ndarray.
*
* @private
* @param {Complex64Array} buffer - underlying data buffer
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {integer} stride0 - stride of the first dimension
* @param {integer} stride1 - stride of the second dimension
* @param {NonNegativeInteger} offset - index offset
* @param {string} [order='row-major'] - storage layout
* @returns {ndarray} two-dimensional ndarray
*/
function matrix( buffer, M, N, stride0, stride1, offset, order ) {
	return new ndarray( 'complex64', buffer, [ M, N ], [ stride0, stride1 ], offset, order || 'row-major' );
}

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Complex64Array} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'complex64', buffer, [ length ], [ stride ], offset, 'row-major' );
}

/**
* Returns a one-dimensional workspace ndarray.
*
* @private
* @param {Uint8Array} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional workspace ndarray
*/
function workspace( buffer, length, stride, offset ) {
	return new ndarray( 'uint8', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof cindexOfColumn, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( cindexOfColumn.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function returns -1 when M is 0 (row-major)', function test( t ) {
	var actual;
	var abuf;
	var xbuf;
	var wbuf;
	var A;
	var x;
	var w;

	abuf = new Complex64Array( 0 );
	xbuf = new Complex64Array( [ 1.0, 0.0 ] );
	wbuf = new Uint8Array( 2 );

	A = matrix( abuf, 0, 2, 2, 1, 0, 'row-major' );
	x = vector( xbuf, 0, 1, 0 );
	w = workspace( wbuf, 2, 1, 0 );

	actual = cindexOfColumn( [ A, x, w ] );
	t.strictEqual( actual, -1, 'returns expected value' );
	t.end();
});

