tape( 'the function returns the index of the first column matching a search vector (row-major)', function test( t ) {
	var actual;
	var abuf;
	var xbuf;
	var wbuf;
	var A;
	var x;
	var w;

	abuf = new Complex64Array([
		1.0,
		0.0,
		2.0,
		0.0,
		3.0,
		0.0,
		4.0,
		0.0,
		5.0,
		0.0,
		6.0,
		0.0
	]);
	xbuf = new Complex64Array([
		2.0,
		0.0,
		4.0,
		0.0,
		6.0,
		0.0
	]);
	wbuf = new Uint8Array( 2 );

	A = matrix( abuf, 3, 2, 2, 1, 0, 'row-major' );
	x = vector( xbuf, 3, 1, 0 );
	w = workspace( wbuf, 2, 1, 0 );

	actual = cindexOfColumn( [ A, x, w ] );
	t.strictEqual( actual, 1, 'returns expected value' );

	xbuf = new Complex64Array([
		1.0,
		0.0,
		3.0,
		0.0,
		5.0,
		0.0
	]);
	x = vector( xbuf, 3, 1, 0 );

	actual = cindexOfColumn( [ A, x, w ] );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

